  for (const j of jobs().filter(j => ['blocked', 'failed'].includes(j.status)).sort((a, b) => Number(b.status === 'failed') - Number(a.status === 'failed'))) items.push({ title: j.title, detail: `${data.projects.find(p => p.id === j.project_id)?.title || j.project_id} · ${j.blocked_reason || j.last_error || j.error || j.result?.summary || 'Inspect the recorded result before deciding whether to retry.'}`, label: 'Inspect job', action: 'inspect-job', id: j.id, kind: j.status === 'failed' ? 'red' : 'amber', type: words(j.status) });
