  if (!matches.length) return empty(data.projects.length ? 'No games match' : 'No games yet', data.projects.length ? 'Change the search or stage filter.' : 'Create a record for an original game, then link its private repository.', data.projects.length ? button('Clear filters', 'clear-games', '', 'small') : button('New game', 'new-project', '', 'primary small'));
