  const header = heading('Reference library', 'Source-linked games for research. Listing identities are verified; gameplay suitability and demand need further evidence.', `${expanded ? '' : `<a class="button" href="/api/export/games.csv">${icon('download')} Export CSV</a>`}${button('Original concepts', 'concepts', '', 'primary')}`) + switcher;
  if (expanded) return header + discoveryResearchPage();
  return header +
    notice('<strong>References, not a top-download ranking.</strong> Current monthly downloads and country rankings have not been verified. All 100 references remain unplayed in this research record.') +
    `<div class="filterbar"><label class="sr-only" for="catalog-query">Search games</label><input class="search-input" id="catalog-query" value="${esc(query)}" placeholder="Search titles or studios…"><label class="sr-only" for="family-filter">Game family</label><select id="family-filter"><option value="">All game families</option>${families.map(f => `<option value="${f}" ${f === family ? 'selected' : ''}>${words(f)}</option>`).join('')}</select><label class="sr-only" for="studio-filter">Publisher</label><select id="studio-filter"><option value="">All publishers</option>${catalog.studios.filter(s => s.group === 'primary').map(s => `<option value="${s.studio_id}" ${s.studio_id === studio ? 'selected' : ''}>${esc(s.studio_or_publisher)}</option>`).join('')}</select>${button(pinsOnly ? '★ Shortlisted only' : '☆ All references', 'toggle-pins', '', 'small')}<span class="results-label" id="results-label"></span></div><div id="catalog-results"></div>`;
