  if (focusedId) { const replacement = document.getElementById(focusedId); if (replacement && replacement !== focused) { replacement.focus({ preventScroll: true }); if (selection && replacement.setSelectionRange) replacement.setSelectionRange(...selection); } }
  else if (focusedAction) { const replacement = [...$('#main').querySelectorAll('[data-action]')].find(control => Object.entries(focusedAction).every(([key, value]) => control.dataset[key] === value)); replacement?.focus({ preventScroll: true }); }
  for (const region of $('#main').querySelectorAll('.table-wrap[aria-label]')) { const label = region.getAttribute('aria-label'); if (tablePositions.has(label)) region.scrollLeft = tablePositions.get(label); if (focusedRegion === label) region.focus({ preventScroll: true }); }
