function markdown(source) {
  // Escape all source text before applying minimal presentation. No raw HTML, scripts, or arbitrary links.
  const inline = s => esc(s).replace(/`([^`]+)`/g, '<code>$1</code>').replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  const lines = source.split('\n'); let out = '', inCode = false, code = [], table = [];
  const flush = () => { if (!table.length) return; const filtered = table.filter(r => !/^\|[\s:|\-]+\|\s*$/.test(r)); out += '<div class="table-wrap"><table><tbody>' + filtered.map((r, i) => '<tr>' + r.split('|').slice(1, -1).map(c => `<${i === 0 ? 'th' : 'td'}>${inline(c.trim())}</${i === 0 ? 'th' : 'td'}>`).join('') + '</tr>').join('') + '</tbody></table></div>'; table = []; };
  for (const line of lines) { if (line.startsWith('```')) { flush(); if (inCode) { out += `<pre>${esc(code.join('\n'))}</pre>`; code = []; } inCode = !inCode; continue; } if (inCode) { code.push(line); continue; } if (line.startsWith('|')) { table.push(line); continue; } flush(); if (/^#{1,3} /.test(line)) out += `<h${Math.min(3, line.match(/^#+/)[0].length + 1)}>${inline(line.replace(/^#+ /, ''))}</h${Math.min(3, line.match(/^#+/)[0].length + 1)}>`; else if (line.trim()) out += `<p>${inline(line)}</p>`; }
  flush(); if (code.length) out += `<pre>${esc(code.join('\n'))}</pre>`; return out;
}
