document.addEventListener('input', event => { if (event.target.id === 'game-query') { gameQuery = event.target.value; renderGames(); } if (event.target.id === 'release-query') { releaseQuery = event.target.value; renderReleases(); } if (event.target.id === 'job-query') { jobQuery = event.target.value; renderJobs(); } if (event.target.id === 'agent-query') { agentQuery = event.target.value; renderAgents(); } if (event.target.id === 'catalog-query') { query = event.target.value; pageIndex = 0; discoveryPageIndex = 0; renderResults(); } });
document.addEventListener('change', event => { if (event.target.id === 'game-stage') { gameStage = event.target.value; renderGames(); } if (event.target.id === 'release-project') { releaseProject = event.target.value; renderReleases(); } if (event.target.id === 'release-status') { releaseStatus = event.target.value; renderReleases(); } if (event.target.id === 'family-filter') { family = event.target.value; pageIndex = 0; renderResults(); } if (event.target.id === 'studio-filter') { studio = event.target.value; pageIndex = 0; renderResults(); } if (event.target.id === 'job-project-filter') { jobProjectFilter = event.target.value; renderJobs(); } if (event.target.id === 'job-status-filter') { jobStatusFilter = event.target.value; renderJobs(); } if (event.target.id === 'job-role-filter') { jobRoleFilter = event.target.value; renderJobs(); } if (event.target.id === 'job-project') renderJobDependencies(); if (event.target.id === 'discovery-category') { discoveryCategory = event.target.value; discoveryPageIndex = 0; renderDiscoveryResults(); } if (event.target.id === 'discovery-complexity') { discoveryComplexity = event.target.value; discoveryPageIndex = 0; renderDiscoveryResults(); } });
document.addEventListener('submit', async event => {
  event.preventDefault(); const form = event.target;
  if (form.id === 'global-search-form') { gameQuery = $('#global-search').value; gameStage = ''; gameView = 'table'; navigate('pipeline'); return; }
  const fields = Object.fromEntries(new FormData(form)), submit = event.submitter; let path, method = 'POST', body;
  if (!submit || submit.disabled) return; submit.disabled = true;
  try {
    if (form.id === 'project-form') { const old = activeModal.record; path = old ? '/api/projects/' + old.id : '/api/projects'; method = old ? 'PATCH' : 'POST'; body = { ...fields, ...(old ? { revision: old.revision, references: old.references } : {}) }; }
    else if (form.id === 'task-form') { path = '/api/tasks/' + activeModal.record.id; method = 'PATCH'; body = { ...fields, revision: activeModal.record.revision }; }
    else if (form.id === 'candidate-form') { path = '/api/candidates'; body = JSON.parse(fields.manifest); if (!fields.project_id || body.project_id !== fields.project_id) throw new Error('The manifest project_id must match the selected game. Download a template for this game or correct the manifest.'); }
    else if (form.id === 'decision-form') { const r = activeModal.record; path = '/api/releases/' + r.id + '/decision'; body = { ...fields, action: submit.value, manifest_hash: r.manifest_hash, playtested_both: fields.playtested_both === 'on', reviewed_evidence: fields.reviewed_evidence === 'on' }; }
    else if (form.id === 'publication-form') { path = '/api/releases/' + activeModal.record.id + '/publication'; body = { ...fields, published_at: fields.published_at + 'T00:00:00.000Z' }; }
    else if (form.id === 'job-form') { path = '/api/jobs'; body = { project_id: fields.project_id, role: fields.role, title: fields.title, instructions: fields.instructions, max_attempts: Number(fields.max_attempts), dependencies: new FormData(form).getAll('dependencies'), idempotency_key: activeModal.idempotencyKey }; }
    else if (form.id === 'cancel-job-form') { path = '/api/jobs/' + encodeURIComponent(activeModal.record.id) + '/cancel'; body = {}; }
    else return;
    const result = await api(path, { method, body: JSON.stringify(body) }); $('#modal').close(); await refresh();
    if (form.id === 'project-form' && method === 'POST') navigate('project/' + result.project.id);
    if (form.id === 'decision-form' && submit.value === 'request_changes') { releaseModal(activeModal.record.id); }
    if (form.id === 'job-form') { jobQuery = ''; jobProjectFilter = body.project_id; jobStatusFilter = ''; jobRoleFilter = ''; navigate('operations'); }
    toast(result.message || (form.id === 'candidate-form' ? 'Review pack saved. No store upload was triggered.' : form.id === 'job-form' ? 'Assignment queued. It waits for dependencies and a matching worker.' : form.id === 'cancel-job-form' ? 'Cancellation recorded. Work already performed is not undone.' : 'Workspace updated.'));
  } catch (error) { const box = $('#form-error'); if (box) { box.textContent = error.message; box.hidden = false; } else toast(error.message, true); }
  finally { if (submit.isConnected) submit.disabled = false; }
});
